(function(){'use strict';const main=document.querySelector('.g-shell');if(!main)return;const panel=document.createElement('details');panel.className='g-panel';panel.style.marginBottom='20px';panel.innerHTML='<summary><strong>Private-session tools: file fingerprints and calendar reminders</strong></summary><p>Files are processed on this device only. Nothing selected here is uploaded. A fingerprint helps compare file bytes; it does not establish authenticity, lawful collection or admissibility.</p><label>Choose up to ten local files (20 MB each)<input id="local-fingerprint-files" type="file" multiple></label><button type="button" id="local-fingerprint-save" class="btn btn-light" disabled>Download local fingerprint manifest</button><pre id="local-fingerprint-status" role="status" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre><button type="button" id="local-calendar-save" class="btn btn-light">Download calendar reminders for recorded due dates</button><p>Calendar files contain generic deadline labels and dates, without case identifiers. Your calendar app controls delivery. Replace earlier imported events if dates change. Navigator sends no background reminder.</p><p id="local-calendar-status" role="status"></p>';main.append(panel);let manifest=[];
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.getElementById('local-fingerprint-files').onchange=async e=>{const status=document.getElementById('local-fingerprint-status'),button=document.getElementById('local-fingerprint-save'),files=[...e.target.files];manifest=[];button.disabled=true;if(files.length>10||files.some(f=>f.size>20*1024*1024)){status.textContent='Select no more than ten files, each at most 20 MB.';e.target.value='';return}e.target.disabled=true;try{for(const file of files){status.textContent='Computing a local fingerprint…';const bytes=await file.arrayBuffer(),digest=await crypto.subtle.digest('SHA-256',bytes);manifest.push({name:file.name,bytes:file.size,sha256:Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('')})}status.textContent=manifest.map(x=>x.name+'\nSHA-256: '+x.sha256).join('\n\n');button.disabled=!manifest.length}catch{manifest=[];status.textContent='Could not compute these fingerprints. No files were uploaded.'}finally{e.target.disabled=false;e.target.value=''}};
document.getElementById('local-fingerprint-save').onclick=()=>{if(manifest.length)download('Local-file-fingerprints.json',JSON.stringify({algorithm:'SHA-256',created:new Date().toISOString(),files:manifest,note:'Local comparison aid, not proof of authenticity or service.'},null,2),'application/json')};
document.getElementById('local-calendar-save').onclick=()=>{const result=window.NavigatorTimelineUI?.getResult(),items=(result?.items||[]).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.due||'')&&!String(x.status).startsWith('completed')),status=document.getElementById('local-calendar-status');if(!items.length){status.textContent='Record and verify the relevant trigger dates first. No due dates are available to export.';return}const compact=d=>d.replaceAll('-',''),lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//POSH Inquiry Navigator//Local reminders//EN','CALSCALE:GREGORIAN'];for(const item of items){const end=new Date(item.due+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+1);lines.push('BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@navigator.local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z'),'DTSTART;VALUE=DATE:'+compact(item.due),'DTEND;VALUE=DATE:'+compact(end.toISOString().slice(0,10)),'SUMMARY:POSH procedural date - verify institutional record','DESCRIPTION:Review the applicable deadline and current source records. No case information included.','BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Review upcoming procedural date','TRIGGER:-P7D','END:VALARM','BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Review upcoming procedural date','TRIGGER:-P1D','END:VALARM','END:VEVENT')}lines.push('END:VCALENDAR');download('POSH-private-calendar-reminders.ics',lines.flatMap(line=>(line.match(/.{1,74}/g)||['']).map((part,i)=>(i?' ':'')+part)).join('\r\n')+'\r\n','text/calendar');status.textContent=items.length+' generic calendar dates exported locally. Import them into your calendar and check its reminder settings.'};
})();
